	if len(content) == 0 {
		return nil
	}

	lines := scanLines(content)
	sections := sectionsOf(lines, len(content), f)
	sections = mergeSmallSections(sections, b)

	var out []passage
	for _, s := range sections {
		for _, span := range subdivide(content, lines, s, b) {
			out = append(out, passage{
				Ordinal:     len(out),
				Heading:     s.heading,
				HeadingPath: s.path,
				Start:       span[0],
				End:         span[1],
				Body:        string(content[span[0]:span[1]]),
			})
		}
	}
	return out
}"},{"id":"c360.semsource-75c46a.workspace.golang.var.handler-doc-splitter-go-defaultBounds","body":"var defaultBounds = passageBounds{ceiling: 2000, floor: 400, hardMax: 6000}"},{"id":"c360.semsource-75c46a.workspace.golang.file.handler-doc-splitter-go","body":""},{"id":"c360.semsource-75c46a.workspace.golang.function.handler-doc-export_test-go-SplitPassagesBounded","body":"func SplitPassagesBounded(content []byte, ceiling, floor, hardMax int, asciidoc bool) []passage {
