"},{"id":"c360.semsource-75c46a.workspace.golang.type.handler-doc-export_test-go-Passage","body":"type Passage = passage"},{"id":"c360.semsource-75c46a.workspace.golang.method.processor-supersession-component-go-Component-runPass","body":"func (c *Component) runPass(ctx context.Context) (passStats, error) {
	release, err := c.runGate.acquire(ctx)
	if err != nil {
		return passStats{}, err
	}
	defer release()

	c.mu.RLock()
	q := c.queryClient
	c.mu.RUnlock()
	if q == nil {
		return passStats{}, fmt.Errorf("supersession not started")
	}

	entities, truncated, err := q.queryPrefixAll(ctx, c.config.Prefix, c.config.maxEntities())
	if err != nil {
		return passStats{}, fmt.Errorf("enumerate entities: %w", err)
	}
	if truncated {
		c.logger.Warn("supersession enumeration hit max_entities cap; correspondence groups "+
			"split across the cap will have incomplete lineage this pass",
			"max_entities", c.config.maxEntities())
	}

	cands := make([]candidate, 0, len(entities))
	existing := make(map[string][]message.Triple, len(entities))
	for i := range entities {
		cand, ok := candidateFromEntity(entities[i])
		if !ok {
			continue
		}
		cands = append(cands, cand)
		existing[cand.id] = entities[i].Triples
	}

	desired, stats := desiredEdges(groupByCorrespondence(cands))
	stats.Entities = len(cands)
	stats.Truncated = truncated

	delta := diffNew(desired, existing)
	updated := c.publishDelta(delta)

	c.mu.Lock()
	c.lastRun = time.Now()
	c.lastStats = stats
	c.mu.Unlock()

	c.logger.Info("supersession pass complete",
		"entities", stats.Entities,
		"groups", stats.Groups,
		"corresponding", stats.Corresponding,
		"supersedes", stats.Supersedes,
		"changed", stats.Changed,
		"incomparable", stats.Incomparable,
		"entities_updated", updated)
	return stats, nil
}"},{"id":"c360.semsource-75c46a.workspace.golang.file.handler-doc-splitter_test-go","body":""},{"id":"c360.semsource-75c46a.workspace.golang.function.handler-doc-homogeneous_test-go-TestDividedBlocksStillTileTheDocument","body":"func TestDividedBlocksStillTileTheDocument(t *testing.T) {
