}"},{"id":"c360.semsource-75c46a.workspace.golang.function.handler-git-entities-go-newCommitEntity","body":"func newCommitEntity(authority entityid.Authority, fullSHA, authorFull, subject, system string, indexedAt time.Time) *CommitEntity {
