	// ID is the fully-qualified 6-part entity identifier.
	ID string

	// Triples are the semantic property and relationship triples for this entity.
	Triples []message.Triple

	// UpdatedAt is when the entity was last observed / indexed.
	UpdatedAt time.Time

	// StorageRef points to where the full content is stored in ObjectStore.
	// When set, large content (e.g. document body) lives in the store rather
	// than inline in a triple. Nil means all content is in Triples.
	StorageRef *message.StorageReference

	// IndexingProfile declares how SemStreams should treat this entity for
	// semantic indexing: content, control, signal, or trace.
	IndexingProfile string

	// Root is the configured source root the entity was read from, as
	// configured (not necessarily absolute). Not a graph fact: the source
	// derives its lifecycle owner key from it. Empty when the entity did not
	// come from a filesystem root.
	Root string
}"}]}

{"nodes":[{"id":"c360.semsource-75c46a.workspace.golang.function.processor-supersession-lifecycle_absent_test-go-TestAbsentSet_ReappearedArtifactIsCleared","body":"func TestAbsentSet_ReappearedArtifactIsCleared(t *testing.T) {
	// The document is marked stale from an earlier pass, and its passages
	// with it.
	fx := docFixture{
		path:       "reports/q4.md",
		count:      2,
		passages:   2,
		markedIdx:  []int{0, 1},
		parentMark: true,
	}

	// The bucket now holds it again, so the completed pass names something
	// else as absent — or nothing at all.
	stat, err := livenessOracle(graph.LifecycleRunRequest{Owner: "owner-a",
		Org:     "acme",
		Systems: []string{"s"},
		Absent:  []string{"reports/some-other-doc.md"},
	})
	if err != nil {
		t.Fatalf("livenessOracle: %v", err)
	}

	toMark, toClear, _ := decideLifecycleActions(fx.build(), graph.LifecycleReasonFileDeleted, stat)

	if len(toMark) != 0 {
		t.Errorf("marked %d entities for a document that is present", len(toMark))
	}
	if len(toClear) != 3 {
		t.Fatalf("cleared %v, want the parent and both passages", toClear)
	}
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.internal-governance-staleness_lifecycle_integration_test-go-TestIntegration_StalenessLifecycle","body":"func TestIntegration_StalenessLifecycle(t *testing.T) {
	ctx := context.Background()
	tc := natstest.New(t,
		natstest.WithJetStream(),
		natstest.WithStreams(natstest.Stream{
			Name:     "GRAPH",
			Subjects: []string{"graph.ingest.entity"},
		}),
	)
	if _, err := BootstrapStandalone(nil); err != nil {
		t.Fatalf("BootstrapStandalone() error = %v", err)
	}

	reg := payloadregistry.New()
	if err := semsourcegraph.RegisterPayloads(reg); err != nil {
		t.Fatalf("RegisterPayloads() error = %v", err)
	}
	mr := metric.NewMetricsRegistry()

	ingest := startGraphIngest(t, ctx, tc.Client, reg, mr)
	t.Cleanup(func() { _ = stopWithin(5*time.Second, ingest.Stop) })
	index := startGraphIndex(t, ctx, tc.Client, mr)
	t.Cleanup(func() { _ = stopWithin(5*time.Second, index.Stop) })
	q := startGraphQuery(t, ctx, tc.Client, mr)
	t.Cleanup(func() { _ = stopWithin(5*time.Second, q.Stop) })

	const org, project = "acme", "svc"
	root := t.TempDir()
	livePath := filepath.Join(root, "live.go")
	deletedPath := filepath.Join(root, "deleted.go")
	if err := os.WriteFile(livePath, []byte("package pkg\n\nfunc Live() int {\n\treturn 1\n}\n"), 0o644); err != nil {
		t.Fatalf("write live.go: %v", err)
	}
	if err := os.WriteFile(deletedPath, []byte("package pkg\n\nfunc Deleted() int {\n\treturn 2\n}\n"), 0o644); err != nil {
		t.Fatalf("write deleted.go: %v", err)
	}

	astCfg, err := json.Marshal(map[string]any{
		"watch_paths": []map[string]any{
			{"path": root, "org": org, "project": project, "languages": []string{"go"}},
		},
		"instance_name":  "ast-source-svc",
		"watch_enabled":  true,
		"index_interval": "", // manual lifecycle triggering below; no periodic sweep noise
	})
	if err != nil {
		t.Fatalf("marshal ast-source config: %v", err)
	}
	discovered, err := astsource.NewComponent(astCfg, component.Dependencies{NATSClient: tc.Client, Platform: types.PlatformMeta{Org: "acme", Platform: "test-a1b2c3"}})
	if err != nil {
		t.Fatalf("ast-source NewComponent: %v", err)
	}
	astComp := discovered.(*astsource.Component)
	if err := astComp.Initialize(); err != nil {
		t.Fatalf("ast-source Initialize: %v", err)
	}
	if err := astComp.Start(ctx); err != nil {
		t.Fatalf("ast-source Start: %v", err)
	}
	t.Cleanup(func() { _ = stopWithin(5*time.Second, astComp.Stop) })

	scfg, _ := json.Marshal(map[string]any{"max_entities": 1000})
	sdiscovered, err := supersession.NewComponent(scfg, component.Dependencies{NATSClient: tc.Client, Platform: types.PlatformMeta{Org: "acme", Platform: "test-a1b2c3"}})
	if err != nil {
		t.Fatalf("supersession NewComponent: %v", err)
	}
	scomp := sdiscovered.(*supersession.Component)
	if err := scomp.Start(ctx); err != nil {
		t.Fatalf("supersession Start: %v", err)
	}
	t.Cleanup(func() { _ = stopWithin(5*time.Second, scomp.Stop) })

	qc := tc.Client

	system := entityid.ScopedSystemSlug(project, "")
	prefix := org + ".test-a1b2c3." + system + ".golang"

	// Wait until both symbols are indexed by the real ast-source component.
	var liveEntity, deletedEntity *semgraph.EntityState
	deadline := time.Now().Add(30 * time.Second)
	for time.Now().Before(deadline) {
		ents := prefixAll(ctx, qc, prefix)
		liveEntity = pickByNameVersion(ents, "Live", "")
		deletedEntity = pickByNameVersion(ents, "Deleted", "")
		if liveEntity != nil && deletedEntity != nil {
			break
		}
		time.Sleep(150 * time.Millisecond)
	}
	if liveEntity == nil || deletedEntity == nil {
		t.Fatalf("not all symbols indexed: live=%v deleted=%v", liveEntity != nil, deletedEntity != nil)
	}

	// --- (1) delete → ast-source's fsnotify fast path auto-triggers the
	// lifecycle pass, marking the deleted symbol's entity. ---
	if err := os.Remove(deletedPath); err != nil {
		t.Fatalf("remove deleted.go: %v", err)
	}
	waitTriple(t, ctx, qc, deletedEntity.ID, source.EntityLifecycleStale, source.LifecycleReasonFileDeleted, 20*time.Second)

	// The marker must never appear on the live sibling.
	if fresh, ok := fetchEntity(ctx, qc, liveEntity.ID); ok && countObject(fresh, source.EntityLifecycleStale, source.LifecycleReasonFileDeleted) > 0 {
		t.Errorf("live entity %s must not carry the staleness marker", liveEntity.ID)
	}

	// Demotion: the marker's negative salience must rank the stale entity
	// below its live sibling, while both stay retained (bounded reorder).
	// WithSignals attaches predicate-salience ranking (matching production
	// code-context wiring); without it, ranking is pure resolve-order +
	// lexical and never reflects the entity.lifecycle.stale weight at all.
	gc, gcErr := fusionnats.New(tc.Client, 0)
	if gcErr != nil {
		t.Fatalf("fusionnats.New() error = %v", gcErr)
	}
	engine, engErr := fusion.NewEngine(
		gc,
		fusion.NewBodyResolver(fusion.MapStoreResolver{}),
		slog.Default(),
		fusion.WithSignals(fusionvocab.New(cco.Parents)),
	)
	if engErr != nil {
		t.Fatalf("fusion.NewEngine() error = %v", engErr)
	}
	lens := prefixLens{code.New()}
	var liveRank, deletedRank int
	rankDeadline := time.Now().Add(20 * time.Second)
	for time.Now().Before(rankDeadline) {
		resp, ferr := engine.Fuse(ctx, fusion.Request{Query: prefix, Want: []fusion.Want{fusion.WantRelations}}, lens)
		if ferr != nil {
			if fuseErrIsRetryable(t, ferr) {
				time.Sleep(100 * time.Millisecond)
				continue
			}
		}
		liveRank = rankByHandle(resp.Nodes, liveEntity.ID)
		deletedRank = rankByHandle(resp.Nodes, deletedEntity.ID)
		if !resp.Deferred && liveRank >= 0 && deletedRank >= 0 {
			break
		}
		time.Sleep(150 * time.Millisecond)
	}
	if liveRank < 0 || deletedRank < 0 {
		t.Fatalf("both entities must be retained and rankable: liveRank=%d deletedRank=%d", liveRank, deletedRank)
	}
	if liveRank >= deletedRank {
		t.Errorf("live entity (rank %d) should outrank the stale entity (rank %d)", liveRank, deletedRank)
	}

	// --- (2) recreate the file + re-run the lifecycle pass → marker cleared. ---
	if err := os.WriteFile(deletedPath, []byte("package pkg\n\nfunc Deleted() int {\n\treturn 3\n}\n"), 0o644); err != nil {
		t.Fatalf("recreate deleted.go: %v", err)
	}
	// Give the watcher's initial re-index a moment before re-running the
	// pass, so the CodePath predicate the pass groups by is definitely
	// present again (a race here just costs an extra pass, never a false
	// clear — the pass only clears entities it finds ALREADY marked AND
	// present on disk).
	time.Sleep(300 * time.Millisecond)
	if _, err := semsourcegraph.PublishLifecycleTrigger(ctx, tc.Client, semsourcegraph.LifecycleRunRequest{
		Org:      org,
		Systems:  []string{system},
		RootPath: root,
		Reason:   semsourcegraph.LifecycleReasonFileDeleted,
		// The AST source's own request shape (#286).
		Owner: semsourcegraph.LifecycleOwner("ast-source-svc", root),
	}); err != nil {
		t.Fatalf("trigger lifecycle pass (recreate): %v", err)
	}
	waitPredicateAbsent(t, ctx, qc, deletedEntity.ID, source.EntityLifecycleStale, 20*time.Second)

	// --- (3) an active producer cannot be removed through the legacy RPC. ---
	if _, err := semsourcegraph.PublishLifecycleTrigger(ctx, tc.Client, semsourcegraph.LifecycleRunRequest{
		Org: org, Systems: []string{system}, Reason: semsourcegraph.LifecycleReasonSourceRemoved,
	}); err == nil || !strings.Contains(err.Error(), "SOURCE_LIFECYCLE_UNAVAILABLE") {
		t.Fatalf("legacy source_removed must explicitly refuse: %v", err)
	}
	assertStalenessRemovalAbsent(ctx, t, qc, liveEntity.ID, deletedEntity.ID)

}"},{"id":"c360.semsource-75c46a.workspace.golang.function.processor-supersession-lifecycle-go-isMarkedStale","body":"func isMarkedStale(triples []message.Triple) bool {
	for i := range triples {
		if triples[i].Predicate == source.EntityLifecycleStale {
			return true
		}
	}
	return false
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.internal-governance-lifecycle_shared_system_integration_test-go-TestIntegration_ASTSweepDoesNotMarkLiveDocsOfSharedProject","body":"func TestIntegration_ASTSweepDoesNotMarkLiveDocsOfSharedProject(t *testing.T) {
	ctx := context.Background()
	tc, deps := startLifecycleStack(t, ctx)

	const org, project = "acme", "svc"
	root := t.TempDir()
	docs := filepath.Join(root, "docs")
	if err := os.MkdirAll(docs, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "live.go"), []byte("package pkg\n\nfunc Live() int {\n\treturn 1\n}\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(docs, "a.md"), []byte("# A\n\nStill here.\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	startDocSource(t, ctx, deps, org, project, docs)

	system := entityid.ScopedSystemSlug(project, "")
	docID := dochandler.DocumentEntityID(fixtureAuthority(), system, "a.md")
	if waitForEntityState(t, ctx, tc.Client, docID, 30*time.Second) == nil {
		t.Fatalf("document %s never reached ENTITY_STATES", docID)
	}

	// The stamp and the sweep must agree on the owner key, or no sweep would
	// ever judge this document.
	if stored, ok := fetchEntity(ctx, tc.Client, docID); !ok ||
		tripleObject(stored.Triples, source.EntityLifecycleOwner) != semsourcegraph.LifecycleOwner("doc-source-svc", docs) {
		t.Fatalf("document %s does not carry its root's owner fact", docID)
	}

	// Count the AST source's own lifecycle requests. A plain subscriber sees
	// every request without answering it; supersession still replies.
	var astSweeps atomic.Int32
	observer, err := tc.Client.Subscribe(ctx, semsourcegraph.LifecycleTriggerSubject, func(_ context.Context, m *nats.Msg) {
		var req semsourcegraph.LifecycleRunRequest
		if json.Unmarshal(m.Data, &req) == nil && req.RootPath == root {
			astSweeps.Add(1)
		}
	})
	if err != nil {
		t.Fatalf("observe lifecycle trigger: %v", err)
	}
	t.Cleanup(func() { _ = observer.Unsubscribe() })

	astCfg, _ := json.Marshal(map[string]any{
		"watch_paths":    []map[string]any{{"path": root, "org": org, "project": project, "languages": []string{"go"}}},
		"instance_name":  "ast-source-svc",
		"watch_enabled":  true,
		"index_interval": "1s",
	})
	ad, err := astsource.NewComponent(astCfg, deps)
	if err != nil {
		t.Fatal(err)
	}
	astComp := ad.(*astsource.Component)
	if err := astComp.Initialize(); err != nil {
		t.Fatal(err)
	}
	if err := astComp.Start(ctx); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = stopWithin(5*time.Second, astComp.Stop) })

	if !testutil.WaitFor(t, 30*time.Second, func() bool { return astSweeps.Load() >= 2 }) {
		t.Fatalf("the AST source sent %d lifecycle sweeps, want at least 2", astSweeps.Load())
	}
	resp, err := semsourcegraph.PublishLifecycleTrigger(ctx, tc.Client, semsourcegraph.LifecycleRunRequest{
		Org: org, Systems: []string{system}, RootPath: root,
		Reason: semsourcegraph.LifecycleReasonPathMissing, Owner: semsourcegraph.LifecycleOwner("ast-source-svc", root),
	})
	if err != nil {
		t.Fatalf("synchronous AST-shaped pass: %v", err)
	}
	if resp.Marked != 0 {
		t.Errorf("AST-shaped pass marked %d entities, want 0: every file under %s exists", resp.Marked, root)
	}
	requireNotStale(t, ctx, tc, docID, filepath.Join(docs, "a.md"))

	// Positive control, the reverse direction: a docs-shaped pass under the
	// wrong root does mark the document, so the assertion above can see a
	// marker when one is written — and it never touches the code entities.
	resp, err = semsourcegraph.PublishLifecycleTrigger(ctx, tc.Client, semsourcegraph.LifecycleRunRequest{
		Org: org, Systems: []string{system}, RootPath: filepath.Join(root, "nowhere"),
		Reason: semsourcegraph.LifecycleReasonPathMissing, Owner: semsourcegraph.LifecycleOwner("doc-source-svc", docs),
	})
	if err != nil {
		t.Fatalf("docs-shaped control pass: %v", err)
	}
	if resp.Marked == 0 {
		t.Fatal("control: a docs pass under a root without a.md marked nothing; the stale assertion cannot see markers")
	}
	e, ok := fetchEntity(ctx, tc.Client, docID)
	if !ok || !hasStaleMarker(e.Triples) {
		t.Fatalf("control: document %s carries no stale marker after a docs pass under the wrong root", docID)
	}
	if resp.Entities != resp.Marked {
		t.Errorf("control pass judged %d entities but marked %d: only the document and its passages answer to a docs root",
			resp.Entities, resp.Marked)
	}
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.processor-supersession-lifecycle_absent_test-go-TestLivenessOracle_AbsentSetAnswersLiveness","body":"func TestLivenessOracle_AbsentSetAnswersLiveness(t *testing.T) {
	stat, err := livenessOracle(graph.LifecycleRunRequest{Owner: "owner-a",
		Org:     "acme",
		Systems: []string{"s"},
		Absent:  []string{"reports/q4.md", "reports/old.md"},
	})
	if err != nil {
		t.Fatalf("livenessOracle: %v", err)
	}
	if stat == nil {
		t.Fatal("an absent set must yield an oracle")
	}

	if stat("reports/q4.md") {
		t.Error("a named path must read as gone")
	}
	// Anything the caller did not name is present. That is what lets an
	// artifact which came back clear its marker on this same pass instead of
	// waiting for a re-seed.
	if !stat("reports/q3.md") {
		t.Error("a path the caller did not name must read as present")
	}
}"},{"id":"c360.semsource-75c46a.workspace.web.chunk.docs-testing-setup-03a-merge-readiness-md-0001","body":"## Accepted baseline and unchanged pins

SemSource remains wholly on SemStreams. The selected extraction/migration SHA remains
`8b99efe9c66a4faa4fa509f9f62cc6bad8392128`, module
`v1.0.0-beta.162.0.20260930150212-8b99efe9c66a`. Tag beta.163 was absent when the work began;
a later release does not move the baseline. [Pins](pins.json) also retain the fixed provider image,
served model/artifacts, vector dimensions and preprocessing used in the paired neural comparisons.

Baseline acceptance means the expected workload and both comparison points are recorded, differences
are attributed, dependency closures include tests, and independently reviewed consumer adaptations
are safe at the pin. It does not mean every intended substrate behavior passes. In particular:

- `broker_restart_reingested_exact_relationship` remains failed at beta.161 and the frozen pin.
- `broker_restart_reingested_exact_content` remains failed at beta.161 and the frozen pin.

Both failures reproduce in BM25 and neural runs. The recorded mechanism is retained applied-sequence
state rejecting changed-source ingestion after memory GRAPH recreation. Memory transport loss itself
is expected; suppressing valid re-ingestion is the defect. The owner classifies these exact cases as
**known-at-pin**, tracked by [SemStreams #1442][ss1442] and [SemEngine #15][engine15]. This classification
permits the measured 03A baseline to merge; it neither proves recovery nor changes the tests' failure
status or process exit. The original failed results stay in [baseline-results.json](baseline-results.json)
and [pinned-results.json](pinned-results.json).

The `Enabled:false` desired-component envelope remains the consumer workaround for file-defined
sources reappearing after deletion. Its removal/restart/re-add behavior is independently tested.
[SemStreams #1443][ss1443] maps to [SemEngine #17][engine17]; removing the workaround is not part of this
baseline delivery.

"},{"id":"c360.semsource-75c46a.workspace.web.chunk.docs-testing-private-recovery-retirement-audit-md-0002","body":"## Evidence and its limits

- Original missing marker: the 9/10 process probe proves an external behavior gap, not an architecture comparison.
- Historical retained-marker repair: process retirement passes prove useful behavior of the selected design,
  not the necessity of its authority.
- Crash after fence before dispatch: an independent fake persistence/replacement test observes zero graph calls,
  then a new coordinator still blocks Add and unrelated Remove.
- Graph failure before desired disable: injected unavailable/degraded tail causes zero healthy config writes.
- Recurring work/state growth: code and a focused two-pass test establish structural cost, not a scale benchmark.
- Settlement/replay/existing-state alternatives: no inspected named proof defeats them; the burden remained unmet.

The independent overlay ran under `-race` and passed in 1.334 seconds:
`TestAuditCrashBeforeDispatchBlocksDisjointAdmissionAfterReplacement` and
`TestAuditGraphFailurePreventsDesiredDisable`. These are deterministic in-memory seam experiments,
not real broker crashes or backend lost-PubAck injections. Existing focused lifecycle tests passed
in 1.345 seconds and the actual Add-guard test in 1.524 seconds. They corroborate the implementation's
admission behavior; they are not corrective implementation results.

Old process facts remain intact: original probe 10/10, sibling restart 8/8, original retirement 16/16,
runtime retirement 20/20, rapid re-add 27/27 and selective reactivation 24/26. The combined run exited 1.
Audit re-reading confirmed all six raw reports matched the versioned hashes. The two failed freshness
assertions stay failed. [Historical final results][results] retain their exact source/binary attribution.

"},{"id":"c360.semsource-75c46a.workspace.golang.function.processor-supersession-lifecycle_passage_test-go-staleMarkerTriple","body":"func staleMarkerTriple(id string) message.Triple {
	return message.Triple{
		Subject:   id,
		Predicate: source.EntityLifecycleStale,
		Object:    graph.LifecycleReasonPassageRemoved,
	}
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.internal-governance-lifecycle_shared_system_integration_test-go-TestIntegration_TwoDocsRootsOfOneProjectDoNotCrossMark","body":"func TestIntegration_TwoDocsRootsOfOneProjectDoNotCrossMark(t *testing.T) {
	ctx := context.Background()
	tc, deps := startLifecycleStack(t, ctx)

	const org, project = "acme", "svc"
	base := t.TempDir()
	rootA, rootB := filepath.Join(base, "a"), filepath.Join(base, "b")
	for root, name := range map[string]string{rootA: "a.md", rootB: "b.md"} {
		if err := os.MkdirAll(root, 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(root, name), []byte("# "+name+"\n\nStill here.\n"), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	startDocSource(t, ctx, deps, org, project, rootA, rootB)

	system := entityid.ScopedSystemSlug(project, "")
	idA := dochandler.DocumentEntityID(fixtureAuthority(), system, "a.md")
	idB := dochandler.DocumentEntityID(fixtureAuthority(), system, "b.md")
	for _, id := range []string{idA, idB} {
		if waitForEntityState(t, ctx, tc.Client, id, 30*time.Second) == nil {
			t.Fatalf("document %s never reached ENTITY_STATES", id)
		}
	}

	sweepA := func() *semsourcegraph.LifecycleRunResponse {
		t.Helper()
		resp, err := semsourcegraph.PublishLifecycleTrigger(ctx, tc.Client, semsourcegraph.LifecycleRunRequest{
			Org: org, Systems: []string{system}, RootPath: rootA,
			Reason: semsourcegraph.LifecycleReasonPathMissing, Owner: semsourcegraph.LifecycleOwner("doc-source-svc", rootA),
		})
		if err != nil {
			t.Fatalf("root A sweep: %v", err)
		}
		return resp
	}
	if resp := sweepA(); resp.Marked != 0 {
		t.Errorf("root A's sweep marked %d entities while every file exists", resp.Marked)
	}
	requireNotStale(t, ctx, tc, idB, filepath.Join(rootB, "b.md"))

	// Root A's own missing artifact is still marked; b.md still is not.
	if err := os.Remove(filepath.Join(rootA, "a.md")); err != nil {
		t.Fatal(err)
	}
	if resp := sweepA(); resp.Marked == 0 {
		t.Fatal("root A's sweep did not mark its own deleted a.md")
	}
	if e, ok := fetchEntity(ctx, tc.Client, idA); !ok || !hasStaleMarker(e.Triples) {
		t.Errorf("document %s carries no stale marker after its file was deleted", idA)
	}
	requireNotStale(t, ctx, tc, idB, filepath.Join(rootB, "b.md"))
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.source-ast-entities_test-go-TestCodeEntity_ExportedMarker","body":"func TestCodeEntity_ExportedMarker(t *testing.T) {
	hasExported := func(e *CodeEntity) bool {
		for _, tr := range e.Triples() {
			if tr.Predicate == CodeExported {
				return true
			}
		}
		return false
	}
	pub := NewCodeEntity(testAuthority("acme"), "golang", "myproject", TypeFunction, "Foo", "pkg/foo.go")
	if !hasExported(pub) {
		t.Error("exported symbol Foo: missing CodeExported marker")
	}
	priv := NewCodeEntity(testAuthority("acme"), "golang", "myproject", TypeFunction, "foo", "pkg/foo.go")
	if hasExported(priv) {
		t.Error("unexported symbol foo: CodeExported marker must NOT be stamped")
	}
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.handler-doc-handler_test-go-TestDocHandler_IngestEntityStates_ParentStaysNavigable","body":"func TestDocHandler_IngestEntityStates_ParentStaysNavigable(t *testing.T) {
	dir := t.TempDir()
	writeMD(t, dir, "guide.md", "# Guide\n\n"+prose("intro", 4)+headedSection("Usage", "usage", 4))

	h, _ := docsHandler(t)
	cfg := sourceConfig{typ: "docs", path: dir}

	states, err := h.IngestEntityStates(context.Background(), cfg, testAuthority("acme"))
	if err != nil {
		t.Fatalf("IngestEntityStates() error: %v", err)
	}
	parents := parentStates(states)
	if len(parents) != 1 {
		t.Fatalf("parent state count: got %d, want 1 (guide.md); %d states in total", len(parents), len(states))
	}
	parent := parents[0]

	if got := tripleValue(t, parent, source.DcTitle); got != "Guide" {
		t.Errorf("%s on %s = %q, want %q; without a title the parent is not name-resolvable",
			source.DcTitle, parent.ID, got, "Guide")
	}
	if got := tripleValue(t, parent, source.DocFilePath); got != "guide.md" {
		t.Errorf("%s on %s = %q, want %q; without a path the parent is not locatable and the staleness pass skips it",
			source.DocFilePath, parent.ID, got, "guide.md")
	}
	if got := tripleValue(t, parent, source.DocMimeType); got != "text/markdown" {
		t.Errorf("%s on %s = %q, want %q", source.DocMimeType, parent.ID, got, "text/markdown")
	}
	if got := tripleValue(t, parent, source.DocFileHash); got == "" {
		t.Errorf("%s on %s is empty; without it a content edit is undetectable", source.DocFileHash, parent.ID)
	}
	if got, want := tripleInt(t, parent, source.DocChunkCount), len(passageStates(states)); got != want {
		t.Errorf("%s on %s = %d, want %d (the number of passages emitted for guide.md)",
			source.DocChunkCount, parent.ID, got, want)
	}
	if got := tripleValue(t, parent, source.DocType); got != "document" {
		t.Errorf("%s on %s = %q, want %q", source.DocType, parent.ID, got, "document")
	}
}"},{"id":"c360.semsource-75c46a.workspace.golang.const.processor-supersession-lifecycle-go-lifecycleEdgeSource","body":"const lifecycleEdgeSource = "lifecycle""},{"id":"c360.semsource-75c46a.workspace.golang.function.source-ast-testpath_test-go-TestCodeEntity_TestMarkerEmission","body":"func TestCodeEntity_TestMarkerEmission(t *testing.T) {
