	)
	if _, err := BootstrapStandalone(nil); err != nil {
		t.Fatalf("BootstrapStandalone() error = %v", err)
	}

	reg := payloadregistry.New()
	if err := semsourcegraph.RegisterPayloads(reg); err != nil {
		t.Fatalf("RegisterPayloads() error = %v", err)
	}
	mr := metric.NewMetricsRegistry()

	ingest := startGraphIngest(t, ctx, tc.Client, reg, mr)
	t.Cleanup(func() { _ = stopWithin(5*time.Second, ingest.Stop) })
	index := startGraphIndex(t, ctx, tc.Client, mr)
	t.Cleanup(func() { _ = stopWithin(5*time.Second, index.Stop) })
	q := startGraphQuery(t, ctx, tc.Client, mr)
	t.Cleanup(func() { _ = stopWithin(5*time.Second, q.Stop) })

	const org, project = "acme", "svc"
	root := t.TempDir()
	livePath := filepath.Join(root, "live.go")
	deletedPath := filepath.Join(root, "deleted.go")
	if err := os.WriteFile(livePath, []byte("package pkg\n\nfunc Live() int {\n\treturn 1\n}\n"), 0o644); err != nil {
		t.Fatalf("write live.go: %v", err)
	}
	if err := os.WriteFile(deletedPath, []byte("package pkg\n\nfunc Deleted() int {\n\treturn 2\n}\n"), 0o644); err != nil {
		t.Fatalf("write deleted.go: %v", err)
	}

	astCfg, err := json.Marshal(map[string]any{
		"watch_paths": []map[string]any{
			{"path": root, "org": org, "project": project, "languages": []string{"go"}},
		},
		"instance_name":  "ast-source-svc",
		"watch_enabled":  true,
		"index_interval": "", // manual lifecycle triggering below; no periodic sweep noise
	})
	if err != nil {
		t.Fatalf("marshal ast-source config: %v", err)
	}
	discovered, err := astsource.NewComponent(astCfg, component.Dependencies{NATSClient: tc.Client, Platform: types.PlatformMeta{Org: "acme", Platform: "test-a1b2c3"}})
	if err != nil {
		t.Fatalf("ast-source NewComponent: %v", err)
	}
	astComp := discovered.(*astsource.Component)
	if err := astComp.Initialize(); err != nil {
		t.Fatalf("ast-source Initialize: %v", err)
	}
	if err := astComp.Start(ctx); err != nil {
		t.Fatalf("ast-source Start: %v", err)
	}
	t.Cleanup(func() { _ = stopWithin(5*time.Second, astComp.Stop) })

	scfg, _ := json.Marshal(map[string]any{"max_entities": 1000})
	sdiscovered, err := supersession.NewComponent(scfg, component.Dependencies{NATSClient: tc.Client, Platform: types.PlatformMeta{Org: "acme", Platform: "test-a1b2c3"}})
	if err != nil {
		t.Fatalf("supersession NewComponent: %v", err)
	}
	scomp := sdiscovered.(*supersession.Component)
	if err := scomp.Start(ctx); err != nil {
		t.Fatalf("supersession Start: %v", err)
	}
	t.Cleanup(func() { _ = stopWithin(5*time.Second, scomp.Stop) })

	qc := tc.Client

	system := entityid.ScopedSystemSlug(project, "")
	prefix := org + ".test-a1b2c3." + system + ".golang"

	// Wait until both symbols are indexed by the real ast-source component.
	var liveEntity, deletedEntity *semgraph.EntityState
	deadline := time.Now().Add(30 * time.Second)
	for time.Now().Before(deadline) {
		ents := prefixAll(ctx, qc, prefix)
		liveEntity = pickByNameVersion(ents, "Live", "")
		deletedEntity = pickByNameVersion(ents, "Deleted", "")
		if liveEntity != nil && deletedEntity != nil {
			break
		}
		time.Sleep(150 * time.Millisecond)
	}
	if liveEntity == nil || deletedEntity == nil {
		t.Fatalf("not all symbols indexed: live=%v deleted=%v", liveEntity != nil, deletedEntity != nil)
	}

	// --- (1) delete → ast-source's fsnotify fast path auto-triggers the
	// lifecycle pass, marking the deleted symbol's entity. ---
	if err := os.Remove(deletedPath); err != nil {
		t.Fatalf("remove deleted.go: %v", err)
	}
	waitTriple(t, ctx, qc, deletedEntity.ID, source.EntityLifecycleStale, source.LifecycleReasonFileDeleted, 20*time.Second)

	// The marker must never appear on the live sibling.
	if fresh, ok := fetchEntity(ctx, qc, liveEntity.ID); ok && countObject(fresh, source.EntityLifecycleStale, source.LifecycleReasonFileDeleted) > 0 {
		t.Errorf("live entity %s must not carry the staleness marker", liveEntity.ID)
	}

	// Demotion: the marker's negative salience must rank the stale entity
	// below its live sibling, while both stay retained (bounded reorder).
	// WithSignals attaches predicate-salience ranking (matching production
	// code-context wiring); without it, ranking is pure resolve-order +
	// lexical and never reflects the entity.lifecycle.stale weight at all.
	gc, gcErr := fusionnats.New(tc.Client, 0)
	if gcErr != nil {
		t.Fatalf("fusionnats.New() error = %v", gcErr)
	}
	engine, engErr := fusion.NewEngine(
		gc,
		fusion.NewBodyResolver(fusion.MapStoreResolver{}),
		slog.Default(),
		fusion.WithSignals(fusionvocab.New(cco.Parents)),
	)
	if engErr != nil {
		t.Fatalf("fusion.NewEngine() error = %v", engErr)
	}
	lens := prefixLens{code.New()}
	var liveRank, deletedRank int
	rankDeadline := time.Now().Add(20 * time.Second)
	for time.Now().Before(rankDeadline) {
		resp, ferr := engine.Fuse(ctx, fusion.Request{Query: prefix, Want: []fusion.Want{fusion.WantRelations}}, lens)
		if ferr != nil {
			if fuseErrIsRetryable(t, ferr) {
				time.Sleep(100 * time.Millisecond)
				continue
			}
		}
		liveRank = rankByHandle(resp.Nodes, liveEntity.ID)
		deletedRank = rankByHandle(resp.Nodes, deletedEntity.ID)
		if !resp.Deferred && liveRank >= 0 && deletedRank >= 0 {
			break
		}
		time.Sleep(150 * time.Millisecond)
	}
	if liveRank < 0 || deletedRank < 0 {
		t.Fatalf("both entities must be retained and rankable: liveRank=%d deletedRank=%d", liveRank, deletedRank)
	}
	if liveRank >= deletedRank {
		t.Errorf("live entity (rank %d) should outrank the stale entity (rank %d)", liveRank, deletedRank)
	}

	// --- (2) recreate the file + re-run the lifecycle pass → marker cleared. ---
	if err := os.WriteFile(deletedPath, []byte("package pkg\n\nfunc Deleted() int {\n\treturn 3\n}\n"), 0o644); err != nil {
		t.Fatalf("recreate deleted.go: %v", err)
	}
	// Give the watcher's initial re-index a moment before re-running the
	// pass, so the CodePath predicate the pass groups by is definitely
	// present again (a race here just costs an extra pass, never a false
	// clear — the pass only clears entities it finds ALREADY marked AND
	// present on disk).
	time.Sleep(300 * time.Millisecond)
	if _, err := semsourcegraph.PublishLifecycleTrigger(ctx, tc.Client, semsourcegraph.LifecycleRunRequest{
		Org:      org,
		Systems:  []string{system},
		RootPath: root,
		Reason:   semsourcegraph.LifecycleReasonFileDeleted,
		// The AST source's own request shape (#286).
		Owner: semsourcegraph.LifecycleOwner("ast-source-svc", root),
	}); err != nil {
		t.Fatalf("trigger lifecycle pass (recreate): %v", err)
	}
	waitPredicateAbsent(t, ctx, qc, deletedEntity.ID, source.EntityLifecycleStale, 20*time.Second)

	// --- (3) an active producer cannot be removed through the legacy RPC. ---
	if _, err := semsourcegraph.PublishLifecycleTrigger(ctx, tc.Client, semsourcegraph.LifecycleRunRequest{
		Org: org, Systems: []string{system}, Reason: semsourcegraph.LifecycleReasonSourceRemoved,
	}); err == nil || !strings.Contains(err.Error(), "SOURCE_LIFECYCLE_UNAVAILABLE") {
		t.Fatalf("legacy source_removed must explicitly refuse: %v", err)
	}
	assertStalenessRemovalAbsent(ctx, t, qc, liveEntity.ID, deletedEntity.ID)

}"},{"id":"c360.semsource-75c46a.workspace.golang.const.graph-lifecycle-go-LifecycleTriggerSubject","body":"const LifecycleTriggerSubject = "graph.lifecycle.run""},{"id":"c360.semsource-75c46a.workspace.golang.const.graph-lifecycle-go-LifecycleReasonFileDeleted","body":"	LifecycleReasonFileDeleted   = "file_deleted""},{"id":"c360.semsource-75c46a.workspace.golang.const.source-vocabulary-lifecycle-go-LifecycleReasonPathMissing","body":"	LifecycleReasonPathMissing   = "path_missing""},{"id":"c360.semsource-75c46a.workspace.golang.const.source-vocabulary-lifecycle-go-EntityLifecycleOwner","body":"const EntityLifecycleOwner = "source.lifecycle.owner""},{"id":"c360.semsource-75c46a.workspace.golang.const.graph-contract-go-GroupLifecycle","body":"	GroupLifecycle = "lifecycle""},{"id":"c360.semsource-75c46a.workspace.golang.const.source-vocabulary-lifecycle-go-LifecycleReasonSourceRemoved","body":"	LifecycleReasonSourceRemoved = "source_removed""},{"id":"c360.semsource-75c46a.workspace.golang.method.processor-supersession-lifecycle-go-Component-runLifecyclePass","body":"func (c *Component) runLifecyclePass(ctx context.Context, req graph.LifecycleRunRequest) (graph.LifecycleRunResponse, error) {
	if req.Reason == graph.LifecycleReasonSourceRemoved {
		return graph.LifecycleRunResponse{}, fmt.Errorf("SOURCE_LIFECYCLE_UNAVAILABLE: source lifecycle projection is unavailable")
	}
	release, err := c.runGate.acquire(ctx)
	if err != nil {
		return graph.LifecycleRunResponse{}, err
	}
	defer release()

	if req.Org == "" || len(req.Systems) == 0 {
		return graph.LifecycleRunResponse{}, fmt.Errorf("lifecycle run: org and systems are required")
	}
	if req.Reason == "" {
		return graph.LifecycleRunResponse{}, fmt.Errorf("lifecycle run: reason is required")
	}

	c.mu.RLock()
	q := c.queryClient
	mut := c.mutClient
	c.mu.RUnlock()
	if q == nil || mut == nil {
		return graph.LifecycleRunResponse{}, fmt.Errorf("supersession not started")
	}

	if req.Org != c.authority.Org {
		return graph.LifecycleRunResponse{}, fmt.Errorf("lifecycle request org %q differs from deployment authority", req.Org)
	}
	prefix := c.authority.Org + "." + c.authority.Platform
	entities, truncated, err := q.queryPrefixAll(ctx, prefix, c.config.maxEntities())
	if err != nil {
		return graph.LifecycleRunResponse{}, fmt.Errorf("enumerate entities: %w", err)
	}

	if truncated {
		return graph.LifecycleRunResponse{}, fmt.Errorf("lifecycle enumeration truncated at max_entities")
	}
	systemSet := make(map[string]struct{}, len(req.Systems))
	for _, s := range req.Systems {
		systemSet[s] = struct{}{}
	}
	statFn, err := livenessOracle(req)
	if err != nil {
		return graph.LifecycleRunResponse{}, err
	}
	inScope := lifecycleScope(entities, systemSet, req.Owner, statFn != nil)
	toMark, toClear, pathCount := decideLifecycleActions(inScope, req.Reason, statFn)

	resp := graph.LifecycleRunResponse{Entities: len(inScope), Paths: pathCount}
	var failures error

	for _, tr := range toMark {
		if err := markStale(ctx, mut, tr); err != nil {
			failures = errors.Join(failures, err)
			continue
		}
		resp.Marked++
	}
	for _, id := range toClear {
		if err := clearStale(ctx, mut, id); err != nil {
			failures = errors.Join(failures, err)
			continue
		}
		resp.Cleared++
	}

	c.logger.Info("lifecycle pass complete",
		"org", req.Org, "systems", req.Systems, "reason", req.Reason, "root_path", req.RootPath,
		"entities", resp.Entities, "paths", resp.Paths, "marked", resp.Marked, "cleared", resp.Cleared)
	return resp, failures
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.processor-supersession-lifecycle-go-decideLifecycleActions","body":"func decideLifecycleActions(inScope []gtypes.EntityState, reason string, stat func(path string) bool) (toMark []message.Triple, toClear []string, pathCount int) {
	if stat == nil {
		// Nothing to check liveness against — the source itself is gone, so
		// every in-scope entity is unconditionally stale.
		for i := range inScope {
			if isMarkedStale(inScope[i].Triples) {
				continue
			}
			toMark = append(toMark, staleTriple(inScope[i].ID, reason))
		}
		return toMark, toClear, 0
	}

	parentCounts := make(map[string]int)
	for _, entity := range inScope {
		if n, ok := tripleInt(entity.Triples, source.DocChunkCount); ok && n >= 0 {
			parentCounts[entity.ID] = n
		}
	}
	byPath := make(map[string][]gtypes.EntityState)
	for i := range inScope {
		p, ok := pathOf(inScope[i].Triples)
		if !ok {
			continue // no path predicate — can't determine liveness
		}
		byPath[p] = append(byPath[p], inScope[i])
	}
	pathCount = len(byPath)

	for path, group := range byPath {
		present := stat(path)
		if !present {
			for i := range group {
				if !isMarkedStale(group[i].Triples) {
					toMark = append(toMark, staleTriple(group[i].ID, reason))
				}
			}
			continue
		}
		// The file is present, but a document that SHRANK leaves passages
		// behind that no filesystem check can see: every passage of a
		// ten-passage document that is now seven passages long still carries
		// the path of a file that is very much still there. The parent's
		// DocChunkCount is the only evidence, so liveness for a passage is
		// index < count rather than stat().
		for i := range group {
			if isSourceRemoved(group[i].Triples) {
				continue
			}
			liveCount, haveCount := passageParentCount(group[i], parentCounts)
			marked := isMarkedStale(group[i].Triples)
			vanished := haveCount && isVanishedPassage(group[i].Triples, liveCount)
			switch {
			case vanished && !marked:
				toMark = append(toMark, staleTriple(group[i].ID, graph.LifecycleReasonPassageRemoved))
			case !vanished && marked:
				// Without the parent's count there is no evidence either way, so
				// clearing a passage's marker here would resurrect a genuinely
				// vanished passage whenever enumeration truncated before its
				// parent — and re-mark it on the next full pass. Absence of
				// evidence must not read as evidence of liveness.
				if !haveCount && isPassage(group[i].Triples) {
					continue
				}
				toClear = append(toClear, group[i].ID)
			}
		}
	}
	return toMark, toClear, pathCount
}"},{"id":"c360.semsource-75c46a.workspace.golang.file.internal-governance-staleness_lifecycle_integration_test-go","body":""},{"id":"c360.semsource-75c46a.workspace.golang.function.processor-supersession-lifecycle_safety_test-go-TestSourceRemovedStickyAcrossLegacyOracles","body":"func TestSourceRemovedStickyAcrossLegacyOracles(t *testing.T) {
	id := "acme.semsource.docs.web.doc.a"
	e := replayEntity(id, graph.LifecycleReasonSourceRemoved)
	for _, stat := range []func(string) bool{func(string) bool { return true }, func(string) bool { return false }, nil} {
		m, c, _ := decideLifecycleActions([]gtypes.EntityState{e}, graph.LifecycleReasonFileDeleted, stat)
		if len(m) > 0 || len(c) > 0 {
			t.Fatalf("legacy changed source_removed: %v %v", m, c)
		}
	}
	oracle, err := livenessOracle(graph.LifecycleRunRequest{Owner: "owner-a", Absent: []string{}})
	if err != nil {
		t.Fatal(err)
	}
	m, c, _ := decideLifecycleActions([]gtypes.EntityState{e}, graph.LifecycleReasonFileDeleted, oracle)
	if len(m) > 0 || len(c) > 0 {
		t.Fatal("empty absent cleared source_removed")
	}
}"},{"id":"c360.semsource-75c46a.workspace.golang.struct.graph-lifecycle-go-LifecycleRunRequest","body":"type LifecycleRunRequest struct {
	Org      string   `json:"org"`
	Systems  []string `json:"systems"`
	RootPath string   `json:"root_path,omitempty"`
	Reason   string   `json:"reason"`

	// Absent is the caller's own answer to the liveness question, for sources
	// whose artifacts are not files and cannot be stat-ed — an object store
	// tells nobody what it holds except by being listed. A non-nil Absent
	// names every path the caller's COMPLETED enumeration found to be gone;
	// every other in-scope path is treated as present, which is what lets a
	// reappeared artifact clear its marker on the same pass.
	//
	// It is mutually exclusive with RootPath: two liveness oracles disagreeing
	// silently is worse than a rejected request.
	//
	// Deliberately without omitempty. An empty non-nil Absent is a real and
	// safe assertion — "my listing completed and nothing is missing" — while a
	// nil one alongside an empty RootPath is the remove_source shape that
	// marks everything in scope. omitempty would collapse the first into the
	// second and retract a whole corpus on a pass that found nothing wrong.
	Absent []string `json:"absent"`

	// Owner is the LifecycleOwner key of the root (or bucket) whose liveness
	// this request answers for. Only in-scope entities whose owner fact
	// (source.lifecycle.owner) equals it are judged. A system slug is shared by
	// every root configured with the same project, so without it one root's
	// sweep would stat another root's artifacts in the wrong directory and mark
	// live entities stale (#286). Required whenever RootPath or Absent is set.
	Owner string `json:"owner,omitempty"`
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.processor-supersession-lifecycle-go-clearStale","body":"func clearStale(ctx context.Context, mut lifecycleMutator, id string) error {
	_, err := mut.Reconcile(ctx, projection.ReconcileMutation{
		Contract: graph.SourceEntityContract().Name,
		Group:    graph.GroupLifecycle,
		EntityID: id,
		Desired:  nil,
		Metadata: projection.MutationMetadata{
			Source:    lifecycleEdgeSource,
			Timestamp: time.Now(),
		},
	})
	if err != nil {
		var ce *errs.ClassifiedError
		if errors.As(err, &ce) && ce.Code == gtypes.ErrorCodeEntityNotFound {
			return nil
		}
		return fmt.Errorf("reconcile lifecycle clear on %s: %w", id, err)
	}
	return nil
}"},{"id":"c360.semsource-75c46a.workspace.golang.struct.processor-objectstore-source-component-go-Component","body":"type Component struct {
	authority entityid.Authority
	name      string
	config    Config
	publisher *entitypub.Publisher
	// seedLoss attributes publisher loss to one seed pass; the publisher's
	// own counters are monotonic and so can never clear.
	seedLoss   seedloss.Tracker
	natsClient *natsclient.Client
	logger     *slog.Logger
	platform   types.PlatformMeta

	handler   *objectstore.Handler
	sourceCfg *sourceCfg
	// system is the entity-ID system segment these documents carry, resolved
	// once: the bucket does not change, and the retraction path must scope by
	// exactly the slug the ingest path published under.
	system string

	// Lifecycle
	running   bool
	startTime time.Time
	mu        sync.RWMutex

	// seed supervises the asynchronous initial ingest (internal/seedsup):
	// Start must return promptly or the framework's component-start barrier
	// keeps the HTTP and metrics listeners from binding (semstreams#867).
	seed seedsup.Supervisor

	// phase is the lifecycle phase the periodic reporter publishes; atomic
	// because the reporter goroutine samples it while Start mutates it.
	phase atomic.Value
	// statusPublishFailing is edge-triggered (ADR-0011): status reporting IS
	// the readiness surface, so a failure must be visible at the default level
	// without logging once per interval while it persists.
	statusPublishFailing degraded.Condition
	// bucketUnreachable: a source that cannot list its prefix ingests nothing,
	// and without this it does so silently for the whole retry window.
	bucketUnreachable degraded.Condition
	// lifecycleFailing: staleness marking has stopped working.
	lifecycleFailing degraded.Condition

	// Metrics
	entitiesPublished atomic.Int64
	ingestErrors      atomic.Int64
	lastActivityMu    sync.RWMutex
	lastActivity      time.Time

	// skipped holds the skip counts of the LAST COMPLETED PASS, not a running
	// total. A skip repeats every pass by nature — an unsupported extension
	// stays unsupported — so a lifetime counter would climb forever while
	// describing the same few objects.
	skippedMu sync.RWMutex
	skipped   map[string]int64

	// distinct tracks distinct entity IDs for honest status counts
	// (publish counters inflate under periodic reindex).
	distinct *entitypub.DistinctTracker

	// Background goroutine cancellation
	cancelFuncs []context.CancelFunc
	workers     workerjoin.Group
}"},{"id":"c360.semsource-75c46a.workspace.golang.function.handler-doc-handler_test-go-TestDocHandler_IngestEntityStates_IDStableAcrossContentChange","body":"func TestDocHandler_IngestEntityStates_IDStableAcrossContentChange(t *testing.T) {
	dir := t.TempDir()
	path := writeMD(t, dir, "doc.md", "# First\nOriginal content.")

	h, _ := docsHandler(t)
	cfg := sourceConfig{typ: "docs", path: dir}

	states1, _ := h.IngestEntityStates(context.Background(), cfg, testAuthority("acme"))

	if err := os.WriteFile(path, []byte("# Second\nDifferent content."), 0644); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	states2, _ := h.IngestEntityStates(context.Background(), cfg, testAuthority("acme"))

	if len(states1) == 0 || len(states2) == 0 {
		t.Fatal("expected states from both ingests")
	}
	if states1[0].ID != states2[0].ID {
		t.Errorf("entity ID must stay stable across a content edit (D3): %q vs %q",
			states1[0].ID, states2[0].ID)
	}
}"}]}
